# build_fig_3_1_path_diagram.R
#
# Figure 3.1 — the hypothesis under test, drawn as a schematic (no data): the
# political class affects turbulence directly, and/or indirectly via political
# trust. PJ, 3 Sep: "keep it as the hypothesis for now - it is the test we
# reject" — content unchanged from the original Manchester talk slide
# (presentations/Manchester 6 May 2026 v16.pdf, pp.34/71), redrawn here in
# book house style (greyscale) rather than the slide's navy/grey/red.
#
# House style: sources the same theme file as every other book figure
# (data_workspace_2026-07/figure_house_theme.R) — hard-boiled title,
# descriptive-only subtitle, no interpretive annotation.
#
# OUTPUT: figures/fig_3_1_path_diagram.png

suppressMessages({library(ggplot2)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))
source(file.path(WKBD_ROOT, "data_workspace_2026-07", "figure_house_theme.R"))

CANVAS_W <- house_width_in()
mm <- function(pt) mm_for(pt, CANVAS_W)

box_w <- 2.5; box_h <- 1.4

nodes <- data.frame(
  x     = c(1.5, 5.0, 8.5),
  y     = c(2.0, 6.0, 2.0),
  label = c("Political\nClass", "Political\nTrust", "Turbulence"),
  fill  = c("#000000", "grey55", "grey25")
)

p <- ggplot() +
  # Direct path (solid, black)
  annotate("segment", x = 1.5 + box_w / 2, y = 2.0, xend = 8.5 - box_w / 2, yend = 2.0,
           colour = "#000000", linewidth = 1.4,
           arrow = arrow(length = unit(0.3, "cm"), type = "closed")) +
  # Indirect path (dashed, grey) — Class -> Trust
  annotate("segment", x = 1.5 + box_w / 2, y = 2.0 + box_h / 2, xend = 5.0 - box_w / 2, yend = 6.0 - box_h / 2,
           colour = "grey55", linewidth = 0.9, linetype = "dashed",
           arrow = arrow(length = unit(0.22, "cm"), type = "closed")) +
  # Indirect path (dashed, grey) — Trust -> Turbulence
  annotate("segment", x = 5.0 + box_w / 2, y = 6.0 - box_h / 2, xend = 8.5 - box_w / 2, yend = 2.0 + box_h / 2,
           colour = "grey55", linewidth = 0.9, linetype = "dashed",
           arrow = arrow(length = unit(0.22, "cm"), type = "closed")) +
  # Legend (as plain text, top-left, house style has no ggplot legend)
  annotate("segment", x = 0.5, xend = 1.3, y = 8.1, yend = 8.1, colour = "#000000", linewidth = 1.4) +
  annotate("text", x = 1.45, y = 8.1, label = "Direct path", hjust = 0, size = mm(8), colour = "grey20") +
  annotate("segment", x = 3.6, xend = 4.4, y = 8.1, yend = 8.1, colour = "grey55", linewidth = 0.9, linetype = "dashed") +
  annotate("text", x = 4.55, y = 8.1, label = "Indirect path", hjust = 0, size = mm(8), colour = "grey20") +
  # Node boxes
  geom_rect(data = nodes,
            aes(xmin = x - box_w / 2, xmax = x + box_w / 2, ymin = y - box_h / 2, ymax = y + box_h / 2),
            fill = nodes$fill, colour = "white", linewidth = 0.8) +
  geom_text(data = nodes, aes(x = x, y = y, label = label),
            colour = "white", fontface = "bold", size = mm(9), lineheight = 0.9) +
  coord_fixed(xlim = c(-1.0, 11.0), ylim = c(-0.5, 9.3), expand = FALSE) +
  labs(
    title    = paste0(
      "Figure 3.1: The relationships between the political class,\n",
      "political trust, and turbulence"
    )
  ) +
  theme_void(base_size = pt_for(PRINTED$axis_text, CANVAS_W)) +
  theme(
    plot.title    = element_text(face = "bold", size = pt_for(PRINTED$title, CANVAS_W), hjust = 0),
    plot.subtitle = element_text(face = "italic", colour = "grey30", size = pt_for(PRINTED$subtitle, CANVAS_W), hjust = 0),
    plot.margin   = margin(10, 10, 5, 10)
  )

OUT <- file.path(PROJECT, "figures/fig_3_1_path_diagram.png")
ggsave(OUT, p, width = CANVAS_W, height = CANVAS_W * 0.66, dpi = HOUSE_DPI, bg = "white")
cat("Figure saved:", OUT, "\n")
